class Solution:
    def brightestPosition(self, lights: List[List[int]]) -> int:
        cand = sorted({p - r for p, r in lights} | {p + r + 1 for p, r in lights})
        bb, bp = 0, cand[0]
        for x in cand:
            b = sum(p - r <= x <= p + r for p, r in lights)
            if b > bb:
                bb, bp = b, x
        return bp

