class Solution {
public:
    int brightestPosition(vector<vector<int>>& lights) {
        set<int> cand;
        for (auto& l : lights) {
            cand.insert(l[0] - l[1]);
            cand.insert(l[0] + l[1] + 1);
        }
        int bb = 0, bp = *cand.begin();
        for (int x : cand) {
            int b = 0;
            for (auto& l : lights)
                if (l[0] - l[1] <= x && x <= l[0] + l[1]) b++;
            if (b > bb) { bb = b; bp = x; }
        }
        return bp;
    }
};

