class Solution:
    def brightestPosition(self, lights: List[List[int]]) -> int:
        events = []
        for p, r in lights:
            events.append((p - r, 1))
            events.append((p + r + 1, -1))
        events.sort(key=lambda e: (e[0], -e[1]))
        cur = best = 0
        ans = -1
        i, n = 0, len(events)
        while i < n:
            x = events[i][0]
            while i < n and events[i][0] == x:
                cur += events[i][1]
                i += 1
            if cur > best:
                best, ans = cur, x
        return ans

