class Solution {
public:
    int brightestPosition(vector<vector<int>>& lights) {
        vector<pair<int,int>> events;
        events.reserve(lights.size() * 2);
        for (auto& l : lights) {
            events.push_back({l[0] - l[1], 1});
            events.push_back({l[0] + l[1] + 1, -1});
        }
        sort(events.begin(), events.end(), [](auto& a, auto& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second > b.second;
        });
        int cur = 0, best = 0, ans = 0;
        size_t i = 0, n = events.size();
        while (i < n) {
            int x = events[i].first;
            while (i < n && events[i].first == x) { cur += events[i].second; i++; }
            if (cur > best) { best = cur; ans = x; }
        }
        return ans;
    }
};

