class Solution {
    public int brightestPosition(int[][] lights) {
        int n = lights.length;
        int[][] events = new int[2 * n][];
        int idx = 0;
        for (int[] l : lights) {
            events[idx++] = new int[]{l[0] - l[1], 1};
            events[idx++] = new int[]{l[0] + l[1] + 1, -1};
        }
        Arrays.sort(events, (a, b) ->
            a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(b[1], a[1]));
        int cur = 0, best = 0, ans = 0;
        int i = 0, m = events.length;
        while (i < m) {
            int x = events[i][0];
            while (i < m && events[i][0] == x) { cur += events[i][1]; i++; }
            if (cur > best) { best = cur; ans = x; }
        }
        return ans;
    }
}

